'use client'

import { useState } from 'react'
import { FiUpload, FiFile, FiTrash2 } from 'react-icons/fi'
import { apiClient } from '@/lib/api/client'

interface Document {
  id: number
  name: string
  uploaded_at: string
}

export default function DocumentsListView() {
  const [documents, setDocuments] = useState<Document[]>([])
  const [uploading, setUploading] = useState(false)
  const [error, setError] = useState('')

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    setUploading(true)
    setError('')

    try {
      const result = await apiClient.uploadDocument(file)
      console.log('Upload success:', result)
      // Refresh documents list
      // await loadDocuments()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Upload failed')
    } finally {
      setUploading(false)
    }
  }

  return (
    <div className="p-6 bg-slate-900 text-white rounded-lg">
      <h2 className="text-2xl font-bold mb-6">Documents</h2>

      {/* Upload Button */}
      <label className="block mb-6">
        <div className="flex items-center justify-center gap-2 px-6 py-3 bg-blue-600 hover:bg-blue-700 rounded-lg cursor-pointer transition">
          <FiUpload className="w-5 h-5" />
          <span>{uploading ? 'Uploading...' : 'Upload Document'}</span>
        </div>
        <input
          type="file"
          onChange={handleFileUpload}
          disabled={uploading}
          className="hidden"
          accept=".pdf,.doc,.docx,.txt"
        />
      </label>

      {error && (
        <div className="bg-red-500/20 border border-red-500/50 text-red-200 px-4 py-2 rounded mb-4">
          {error}
        </div>
      )}

      {/* Documents List */}
      <div className="space-y-2">
        {documents.length === 0 ? (
          <p className="text-gray-400 text-center py-8">No documents uploaded yet</p>
        ) : (
          documents.map((doc) => (
            <div key={doc.id} className="flex items-center justify-between bg-slate-800 p-4 rounded">
              <div className="flex items-center gap-3">
                <FiFile className="w-5 h-5 text-blue-400" />
                <div>
                  <p className="font-medium">{doc.name}</p>
                  <p className="text-sm text-gray-400">
                    {new Date(doc.uploaded_at).toLocaleDateString()}
                  </p>
                </div>
              </div>
              <button className="text-red-400 hover:text-red-300">
                <FiTrash2 className="w-5 h-5" />
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  )
}